UPDATE  /* SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbssimListMapper.updateReply : 게시글수정 */
        AYE110  
SET
        CMNT_CN                =       #{CMNT_CN}
    ,   CNTN_IP_ADDR           =       #{CNTN_IP_ADDR}
    ,   LAST_MDFCN_DT          =       SYSDATE      
    ,   LAST_MDFR_ID           =       #{LAST_MDFR_ID}
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       #{BBSCTT_TYPE_SE_CD}                   /*  게시판유형구분코드  */
    AND CMNT_ESNTAL_NO         =       #{CMNT_ESNTAL_NO}

	UPDATE  /* SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbssimListMapper.deleteReply : 댓글삭제 */
	        AYE110 
	SET
            DEL_YN                 =       'Y'
        ,   LAST_MDFCN_DT          =       SYSDATE      
        ,   LAST_MDFR_ID           =       #{LAST_MDFR_ID}    
    WHERE   1=1
        AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
        AND BBSCTT_TYPE_SE_CD      =       #{BBSCTT_TYPE_SE_CD}                   /*  게시판유형구분코드  */
        AND CMNT_ESNTAL_NO         =       #{CMNT_ESNTAL_NO}

UPDATE  
        AYE100  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO        =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD       =       #{BBSCTT_TYPE_SE_CD}                   /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbssimListMapper.updateCrisisBoard : 웹심리 위기유형등록 */
        AYA110  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       #{BBSCTT_TYPE_SE_CD}                  /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbssimListMapper.updateCrisisPerson : 웹심리 위기유형등록 */
        AYA120  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   CLIENA_ID               =       #{CLIENA_ID}
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       #{BBSCTT_TYPE_SE_CD}                   /*  게시판유형구분코드  */

mapper.insert:
INSERT  /* isry.couns.constt.medscsnntabrd.mapper.BbscttListMapper.insertMemo : 비밀게시판 메모등록 */
INTO
        AYA160
(
        RFRNC_NO
    ,   BBSCTT_ESNTAL_NO
    ,   BBSCTT_TYPE_SE_CD
    ,   CONSTT_ID
    ,   MEMO_NM
    ,   FRST_RGTR_ID
    ,   FRST_REG_DT
    ,   LAST_MDFR_ID
    ,   LAST_MDFCN_DT
)
VALUES
(
        AYA160_SQ01.NEXTVAL
    ,   #{BBSCTT_ESNTAL_NO}
    ,   #{BBSCTT_TYPE_SE_CD}
    ,   #{CONSTT_ID}
    ,   #{MEMO_NM}
    ,   #{FRST_RGTR_ID}
    ,   SYSDATE
    ,   #{LAST_MDFR_ID}
    ,   SYSDATE
)

